'use strict';
window.EnsoLab=(()=>{
const phases={
neutral:{name:'平常（中性）',en:'ENSO-neutral',wind:'典型信風',warm:'暖水主要聚集西側',up:'典型上湧',strength:1,west:278,east:211,rise:155,summary:'信風將表層暖水向西輸送，東太平洋的溫躍層較淺，冷水較容易上湧。',walker:'典型沃克環流：西側上升、東側下沉。',rain:'對流降雨主要在西側',detail:'西太平洋的暖水層較深，東側較淺。中性表示接近長期平均，不代表海洋完全不變。'},
nino:{name:'聖嬰',en:'El Niño',wind:'信風減弱',warm:'暖水向中東側擴展',up:'上湧減弱',strength:.48,west:244,east:248,rise:385,summary:'信風減弱，暖水向中、東太平洋擴展；東側暖水層加深，冷水上湧受到抑制。',walker:'沃克環流減弱，上升與對流區向東移。',rain:'對流降雨區偏向中東側',detail:'中、東赤道太平洋海溫高於平均。這裡以典型情境呈現；每次事件的強度與分布會不同。'},
nina:{name:'反聖嬰',en:'La Niña',wind:'信風增強',warm:'暖水更集中於西側',up:'上湧增強',strength:1.5,west:298,east:193,rise:135,summary:'信風增強，更多暖水堆積在西側；東側溫躍層較淺，冷水上湧增強。',walker:'典型沃克環流增強，對流區偏西。',rain:'對流降雨更偏向西側',detail:'中、東赤道太平洋海溫低於平均。反聖嬰與中性同屬「非聖嬰」，因此分開比較。'}
};
function warmth(id,t){return id==='nino'?.96-.33*t:id==='nina'?Math.max(.05,1.1-1.55*t):Math.max(.08,1.06-1.12*t)}
function color(id,t){return d3.interpolateRgbBasis(['#429bb5','#72bfc4','#e7d79e','#f3a16e','#df745e'])(warmth(id,t))}
function drawSurface(ctx,projection,id){ctx.save();ctx.globalAlpha=.64;const path=d3.geoPath(projection,ctx);for(let lon=150;lon<280;lon+=5){for(let lat=-9;lat<9;lat+=3){ctx.fillStyle=color(id,(lon-150)/130);ctx.beginPath();path({type:'Polygon',coordinates:[[[lon,lat],[lon,lat+3],[lon+5,lat+3],[lon+5,lat],[lon,lat]]]});ctx.fill()}}ctx.restore()}
function drawWinds(ctx,projection,id,visible,onScreen,width,phase=0){const s=phases[id].strength;ctx.save();ctx.globalAlpha=.9;ctx.strokeStyle='#557f82';ctx.fillStyle='#557f82';ctx.lineWidth=1.1+s;for(const lat of [-5,5])for(let lon=165;lon<=270;lon+=23){const a=[lon,lat],b=[lon-10*s,lat];if(!visible(a)||!visible(b))continue;const p=projection(a),q=projection(b);if(!onScreen(p)||!onScreen(q)||Math.abs(p[0]-q[0])>width*.3)continue;ctx.setLineDash([4,3]);ctx.lineDashOffset=-phase*8;ctx.beginPath();ctx.moveTo(...p);ctx.lineTo(...q);ctx.stroke();ctx.setLineDash([]);const th=Math.atan2(q[1]-p[1],q[0]-p[0]);ctx.beginPath();ctx.moveTo(...q);ctx.lineTo(q[0]-6*Math.cos(th-.5),q[1]-6*Math.sin(th-.5));ctx.lineTo(q[0]-6*Math.cos(th+.5),q[1]-6*Math.sin(th+.5));ctx.closePath();ctx.fill()}ctx.restore()}
function diagram(id,prefix){const p=phases[id],tc='M50,'+p.west+' Q320,'+((p.west+p.east)/2)+' 590,'+p.east;const warm='M50,170 H590 V'+p.east+' Q320,'+((p.west+p.east)/2)+' 50,'+p.west+' Z';const x=p.rise,stroke=id==='nino'?'stroke-dasharray="5 6"':'';
return '<svg class="enso-svg" viewBox="0 0 640 330" role="img" aria-labelledby="'+prefix+'title '+prefix+'desc"><title id="'+prefix+'title">'+p.name+'：赤道太平洋東西向剖面</title><desc id="'+prefix+'desc">'+p.summary+' '+p.walker+' 高度與深度均為概念示意。</desc><defs><linearGradient id="'+prefix+'warm"><stop stop-color="'+color(id,0)+'"/><stop offset="50%" stop-color="'+color(id,.5)+'"/><stop offset="100%" stop-color="'+color(id,1)+'"/></linearGradient><marker id="'+prefix+'air" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10 Z" fill="#557f82"/></marker><marker id="'+prefix+'water" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L10 5 L0 10 Z" fill="#173f55"/></marker><marker id="'+prefix+'up" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 L10 5 L0 10 Z" fill="#1b6b83"/></marker></defs>'+
'<rect x="50" y="170" width="540" height="145" rx="3" fill="#8fc0d3"/><path d="'+warm+'" fill="url(#'+prefix+'warm)"/><path class="thermocline" data-west="'+p.west+'" data-east="'+p.east+'" d="'+tc+'" fill="none" stroke="#466477" stroke-width="2.5" stroke-dasharray="7 5"/><path d="M50,170 H590" stroke="#285f71" stroke-width="2"/>'+
'<g fill="none" stroke="#557f82" stroke-width="'+(1.5+p.strength)+'" marker-end="url(#'+prefix+'air)" '+stroke+'><path class="flowline" d="M'+x+',132 V55"/><path class="flowline" d="M'+(x+10)+',43 H550"/><path class="flowline" d="M565,55 V132"/></g>'+
[230,340,450,560].map(v=>'<path class="trade-arrow flowline" d="M'+v+',150 h-'+(48*p.strength)+'" fill="none" stroke="#557f82" stroke-width="'+(1.5+p.strength)+'" marker-end="url(#'+prefix+'air)"/>').join('')+
'<g fill="#c6dce5"><ellipse cx="'+x+'" cy="99" rx="34" ry="12"/><ellipse cx="'+(x-12)+'" cy="90" rx="16" ry="15"/><ellipse cx="'+(x+10)+'" cy="87" rx="20" ry="17"/></g><g stroke="#52899c" stroke-width="2">'+[-15,0,15].map(v=>'<path d="M'+(x+v)+',116 l-5,13"/>').join('')+'</g>'+
'<text x="320" y="27" text-anchor="middle" fill="#47697c" font-size="18">沃克環流（大氣）</text><text x="143" y="214" fill="#173f4c" font-size="20" font-weight="600">暖水層</text><text x="320" y="303" fill="#173f55" font-size="18" text-anchor="middle">較冷的深層海水</text>'+
'<path class="water-transport flowline" d="'+(id==='nino'?'M270,190 H490':'M490,190 H270')+'" stroke="#173f55" stroke-width="3" fill="none" marker-end="url(#'+prefix+'water)"/>'+
'<path class="upwelling flowline" d="M550,295 V188" stroke="#1b6b83" stroke-width="'+(2*p.strength+1)+'" opacity="'+(id==='nino'?'.55':'.95')+'" fill="none" marker-end="url(#'+prefix+'up)"/>'+
'</svg>'}
function card(id,prefix){const p=phases[id];return '<article class="enso-diagram" data-phase="'+id+'"><div class="diagram-head"><h4>'+p.name+'</h4><span>'+p.en+'</span></div><div class="diagram-position"><span>西｜印尼附近</span><span>東｜南美洲附近</span></div>'+diagram(id,prefix)+'<div class="diagram-keys"><span><i class="key-air"></i>'+p.wind+'</span><span><i class="key-thermo"></i>虛線：溫躍層</span><span><i class="key-up"></i>'+p.up+'</span></div><p class="walker-note">'+p.walker+'</p><p class="transport-note">'+(id==='nino'?'深藍水平箭頭：暖水向東重分布的調整示意。上湧減弱，並非完全停止。':'深藍水平箭頭：近赤道表層水向西輸送的概念示意。')+'</p></article>'}
const tasks=[
{title:'先看風',q:'從平常切換到聖嬰，你預測信風會變強，還是變弱？畫面的哪些線索能支持你的說法？',answer:'聖嬰情境的信風較弱，因此箭頭縮短、線條變細。反聖嬰則呈現較強的信風。箭頭長度是相對強弱示意，沒有代表實際風速。'},
{title:'再看暖水',q:'信風變弱之後，原本聚集西側的暖水可能如何重新分布？請比較海溫色塊與剖面。',answer:'暖水向中、東太平洋擴展，東側暖水層加深。這是海洋與大氣共同調整的概念示意，並不表示全球洋流都會反向。'},
{title:'解釋上湧',q:'聖嬰情境下，東太平洋的溫躍層變深，較冷的深層海水還容易影響表面海溫嗎？',answer:'東側溫躍層較深，加上風場改變，上湧對海表的冷卻作用減弱，中、東太平洋表面較暖。反聖嬰時，上湧增強、海表較冷。'}
];
return {phases,tasks,drawSurface,drawWinds,card,warmth};
})();
